    [arrowColor],
  )

  const arrowStyle = useMemo(
    () => ({
      ...computedPosition.tooltipArrowStyles,
      background: arrowBackground,
      '--rt-arrow-size': `${arrowSize}px`,
    }),
    [computedPosition.tooltipArrowStyles, arrowBackground, arrowSize],
  )

  useImperativeHandle(forwardRef, () => ({
    open: (options) => {
      let imperativeAnchor: HTMLElement | null = null
      if (options?.anchorSelect) {
        try {
          imperativeAnchor = document.querySelector<HTMLElement>(options.anchorSelect)
        } catch {
          if (!process.env.NODE_ENV || process.env.NODE_ENV !== 'production') {
            console.warn(`[react-tooltip] "${options.anchorSelect}" is not a valid CSS selector`)
          }
          return
        }
        if (!imperativeAnchor) {
          return
        }
      }
      if (imperativeAnchor) {
        setActiveAnchor(imperativeAnchor)
      }
      setImperativeOptions(options ?? null)
      if (options?.delay) {
        handleShowTooltipDelayed(options.delay)
      } else {
        handleShow(true)
      }
    },
    close: (options) => {
      if (options?.delay) {
        handleHideTooltipDelayed(options.delay)
      } else {
        handleShow(false)
      }
    },
    activeAnchor,
    place: computedPosition.place,
    isOpen: Boolean(rendered && !hidden && hasContent && canShow),
  }))

  useEffect(() => {
    return () => {
      // Final cleanup to ensure no memory leaks
      clearTimeoutRef(tooltipShowDelayTimerRef)
      clearTimeoutRef(tooltipHideDelayTimerRef)
      clearTimeoutRef(tooltipAutoCloseTimerRef)
      clearTimeoutRef(missedTransitionTimerRef)
    }
  }, [])

  const tooltipNode =
    rendered && !hidden && hasContent ? (
      <WrapperElement
        id={id}
        role={role}
        className={clsx(
          'react-tooltip',
          coreStyles['tooltip'],
          styles['tooltip'],
          styles[variant],
          className,
          `react-tooltip__place-${computedPosition.place}`,
          coreStyles[canShow ? 'show' : 'closing'],
          canShow ? 'react-tooltip__show' : 'react-tooltip__closing',
          positionStrategy === 'fixed' && coreStyles['fixed'],
          clickable && coreStyles['clickable'],
        )}
        onTransitionEnd={(event: TransitionEvent) => {
          clearTimeoutRef(missedTransitionTimerRef)
          if (show || event.propertyName !== 'opacity') {
            return
          }
          setRendered(false)
          setImperativeOptions(null)
          afterHide?.()
        }}
        style={tooltipStyle}
        ref={tooltipRef}
      >
        <WrapperElement
          className={clsx(
            'react-tooltip-content-wrapper',
            coreStyles['content'],
            styles['content'],
          )}
        >
          {actualContent}
        </WrapperElement>

import React, { useState } from 'react'
import { render, screen, fireEvent } from '@testing-library/react'
import '@testing-library/jest-dom'
import { TooltipController } from '../components/TooltipController'
import {
  advanceTimers,
  flushPendingTimers,
  hoverAnchor,
  unhoverAnchor,
  waitForTooltip,
  waitForTooltipToClose,
} from './test-utils'
import { installMockMutationObserver } from './mutation-observer-test-utils'

jest.mock('@floating-ui/dom', () => {
  const originalModule = jest.requireActual('@floating-ui/dom')
  return {
    ...originalModule,
    autoUpdate: jest.fn(() => jest.fn()),
  }
})

describe('tooltip close and delay behavior', () => {
  let mutationObserverController

  beforeEach(() => {
    jest.useFakeTimers()
    jest.clearAllMocks()
    mutationObserverController = installMockMutationObserver()
  })

  afterEach(() => {
    flushPendingTimers()
    mutationObserverController.restore()
    jest.useRealTimers()
  })

  test('ignores unsupported custom DOM events', async () => {
    render(
      <>
        <span data-tooltip-id="custom-events-test">Hover Me</span>
        <TooltipController
          id="custom-events-test"
          content="Custom Events Test"
          openEvents={{ customopen: true }}
          closeEvents={{ customclose: true }}
        />
      </>,
    )

    const anchor = screen.getByText('Hover Me')

    anchor.dispatchEvent(new Event('customopen', { bubbles: true }))
    advanceTimers(50)
    expect(document.getElementById('custom-events-test')).not.toBeInTheDocument()
  })

  test('closes a clickable tooltip after leaving its content', async () => {
    render(
      <>
        <span data-tooltip-id="clickable-no-click-test">Hover Me</span>
        <TooltipController
          id="clickable-no-click-test"
          content="Clickable No Click Test"
          clickable
        />
      </>,
    )

    const anchor = screen.getByText('Hover Me')

    hoverAnchor(anchor, 100)
    const tooltip = await waitForTooltip('clickable-no-click-test')

    unhoverAnchor(anchor)
    fireEvent.mouseEnter(tooltip)
    expect(screen.getByRole('tooltip')).toBeInTheDocument()

    fireEvent.mouseLeave(tooltip)
    advanceTimers(100)
    // Second advancement needed: the first fires handleShow(false) timeout,
    // which creates the missedTransitionTimer during the effect flush
    advanceTimers(100)
    await waitForTooltipToClose('clickable-no-click-test')
  })

  test('stays stable when anchorSelect matches are removed', () => {
    const SelectorWithRemovedNodesTest = () => {
      const [showElement, setShowElement] = useState(true)

      return (
        <div>
          {showElement && (
            <div className="selector-container">
              <span className="selector-target">Target Element</span>
            </div>
          )}
